/**
 * Threshold cross-validation: Threshold.parse / encode / satisfied against keripy 1.3.4 `Tholder`
 * (generated by scripts/generate-keripy-threshold.py). keripy is the reference (spec §4f, RP9).
 */
import { describe, expect, test } from 'bun:test';
import { Threshold } from '../../common/types.js';
import expectedJson from './threshold-expected.json';

type Case = {
  name: string;
  sith: Threshold;
  keyCount: number;
  error?: string;
  weighted?: boolean;
  size?: number;
  encoded?: Threshold;
  thold?: number | string[][];
  satisfy?: { indices: number[]; satisfied: boolean }[];
};

type WitnessCase = { name: string; bt: string; witnessCount: number; accepted: boolean; error?: string };
const fixture = expectedJson as unknown as { cases: Case[]; lenient: Case[]; witness: WitnessCase[] };
const cases = fixture.cases;

/**
 * Documented divergences (spec §4f): keripy accepts these non-canonical inputs, kerits accepts only keripy's
 * canonical encoding (keripy-produced events always use it, so interop holds). Each entry is kerits' strict
 * result: a parse error kind, or (for a parseable sith) the satisfy() results.
 */
const KNOWN_DIVERGENCES: Record<string, { parse: Threshold.ErrorKind } | { satisfy: boolean[] }> = {
  'lenient-hex-0x-prefix': { parse: 'malformed' },
  'lenient-hex-leading-space': { parse: 'malformed' },
  'lenient-hex-underscore': { parse: 'malformed' },
  'lenient-weight-decimal-1.0': { parse: 'malformed' },
  'lenient-weight-exponent': { parse: 'malformed' },
  'lenient-weight-leading-space': { parse: 'malformed' },
  'lenient-weight-map': { parse: 'malformed' },
  'lenient-negative-index': { satisfy: [false] },
};

/** kerits' error kind for each case keripy rejects (keripy raises untyped errors). */
const ERROR_KIND: Record<string, Threshold.ErrorKind> = {
  'hex-10-of-10-keys': 'out-of-range',
  'm-greater-than-n': 'out-of-range',
  'bare-fraction': 'bare-fraction',
  'bare-fraction-1-of-1': 'bare-fraction',
  'empty-string': 'empty',
  'not-hex': 'malformed',
  negative: 'malformed',
  'empty-list': 'empty',
  'clause-under-one': 'clause-under-one',
  'nested-clause-under-one': 'clause-under-one',
  'weight-over-one': 'out-of-range',
  'weight-int-2': 'out-of-range',
  'weight-zero-denominator': 'malformed',
  'weight-decimal': 'malformed',
  'weight-not-a-number': 'malformed',
  'weighted-size-greater-than-keys': 'size-mismatch',
  'mixed-flat-and-nested': 'malformed',
  'empty-clause': 'clause-under-one',
};

/** keripy's thold, in the fixture's form (fractions as "n/d"). */
function thold(parsed: Threshold.Parsed): number | string[][] {
  if (parsed.kind === 'numeric') {
    return parsed.m;
  } else if (parsed.kind === 'weighted') {
    return parsed.clauses.map((c) => c.map((f) => `${f.numerator}/${f.denominator}`));
  } else {
    throw new Error('unknown threshold kind');
  }
}

describe('Threshold vs keripy Tholder', () => {
  test('the fixture covers every rejected case with a kerits error kind', () => {
    // every keripy-rejected case has an expected kerits kind, and no stale kinds remain
    expect(cases.filter((c) => c.error !== undefined).map((c) => c.name)).toEqual(Object.keys(ERROR_KIND));
  });

  for (const c of cases) {
    test(c.name, () => {
      // call our method under test
      const parsed = Threshold.parse(c.sith, c.keyCount);

      if (c.error !== undefined) {
        // keripy rejects: kerits rejects with the mapped kind
        expect(parsed.ok).toBe(false);
        expect(parsed.ok ? undefined : parsed.error.kind).toBe(ERROR_KIND[c.name]!);
      } else if (parsed.ok) {
        // keripy accepts: same kind, size, parsed weights, wire form and satisfaction
        expect(parsed.value.kind).toBe(c.weighted ? 'weighted' : 'numeric');
        expect(Threshold.size(parsed.value)).toBe(c.size!);
        expect(thold(parsed.value)).toEqual(c.thold!);
        expect(Threshold.encode(parsed.value)).toEqual(c.encoded!);
        expect(Threshold.canonical(c.sith, c.keyCount)).toEqual(c.encoded!);
        expect(c.satisfy!.map((s) => ({ indices: s.indices, satisfied: Threshold.satisfied(parsed.value, s.indices) }))).toEqual(
          c.satisfy!,
        );
      } else {
        throw new Error(`kerits rejected ${c.name}: ${parsed.error.message}`);
      }
    });
  }
});

describe('Threshold vs keripy: known divergences (kerits strict, keripy lenient)', () => {
  test('every lenient vector is listed, and none is stale', () => {
    expect(fixture.lenient.map((c) => c.name)).toEqual(Object.keys(KNOWN_DIVERGENCES));
  });

  for (const c of fixture.lenient) {
    test(c.name, () => {
      const strict = KNOWN_DIVERGENCES[c.name]!;

      // keripy's recorded verdict is lenient: it accepted the sith
      expect(c.error).toBeUndefined();

      // call our method under test
      const parsed = Threshold.parse(c.sith, c.keyCount);

      // kerits is strict
      if ('parse' in strict) {
        expect(parsed.ok ? undefined : parsed.error.kind).toBe(strict.parse);
      } else if (parsed.ok) {
        // keripy satisfied these index sets; kerits doesn't
        expect(c.satisfy!.map((s) => s.satisfied)).toEqual(strict.satisfy.map((v) => !v));
        expect(c.satisfy!.map((s) => Threshold.satisfied(parsed.value, s.indices))).toEqual(strict.satisfy);
      } else {
        throw new Error(`kerits rejected ${c.name}: ${parsed.error.message}`);
      }
    });
  }
});

/** kerits' error kind for each witness case keripy rejects (keripy raises an untyped "Invalid toad"). */
const WITNESS_ERROR_KIND: Record<string, Threshold.ErrorKind> = {
  'bt-1-no-witnesses': 'out-of-range',
  'bt-0-with-witnesses': 'out-of-range',
  'bt-3-of-2': 'out-of-range',
  'bt-10-of-10': 'out-of-range',
};

describe('Threshold.witness vs keripy toad bounds', () => {
  test('the fixture covers every rejected witness case with a kerits error kind', () => {
    // every keripy-rejected case has an expected kind, and no stale kinds remain
    expect(fixture.witness.filter((c) => !c.accepted).map((c) => c.name)).toEqual(Object.keys(WITNESS_ERROR_KIND));
  });

  for (const c of fixture.witness) {
    test(c.name, () => {
      // call our method under test
      const bt = Threshold.witness(c.bt, c.witnessCount);

      // same verdict as keripy's incept / Kever: the hex value when accepted, the mapped kind when rejected
      if (c.accepted) {
        expect(bt).toEqual({ ok: true, value: Number.parseInt(c.bt, 16) });
      } else {
        expect(bt.ok ? undefined : bt.error.kind).toBe(WITNESS_ERROR_KIND[c.name]!);
      }
    });
  }
});
